package com.bplus.share;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.os.*;import android.net.Uri;import android.widget.*;import java.io.*;
public class CropActivity extends Activity{
 private CropView crop;
 protected void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.crop_photo),true,null));try{Uri u=Uri.parse(getIntent().getStringExtra("uri"));BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(u)){BitmapFactory.decodeStream(in,null,o);}o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1400||o.outHeight/o.inSampleSize>1400)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap image;try(InputStream in=getContentResolver().openInputStream(u)){image=BitmapFactory.decodeStream(in,null,o);}if(image==null)throw new IOException();crop=new CropView(image);root.addView(crop,Ui.lpW1());root.addView(Ui.sub(this,getString(R.string.crop_hint)));TextView use=Ui.cta(this,getString(R.string.use_photo));root.addView(use);use.setOnClickListener(v->{try{Bitmap selected=crop.result();ByteArrayOutputStream out=new ByteArrayOutputStream();selected.compress(Bitmap.CompressFormat.JPEG,85,out);Store.set("photo",android.util.Base64.encodeToString(out.toByteArray(),2));setResult(RESULT_OK);finish();}catch(Exception e){Toast.makeText(this,R.string.file_open_failed,1).show();}});setContentView(root);}catch(Exception e){Toast.makeText(this,R.string.file_open_failed,1).show();finish();}}
 private class CropView extends View{
  Bitmap image;Paint p=new Paint(3);float scale,min,x,y,lastX,lastY;RectF box=new RectF();ScaleGestureDetector pinch;
  CropView(Bitmap b){super(CropActivity.this);image=b;pinch=new ScaleGestureDetector(CropActivity.this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){float old=scale;scale=Math.max(min,Math.min(min*5,scale*d.getScaleFactor()));x=d.getFocusX()-(d.getFocusX()-x)*scale/old;y=d.getFocusY()-(d.getFocusY()-y)*scale/old;clamp();invalidate();return true;}});}
  protected void onSizeChanged(int w,int h,int ow,int oh){float side=Math.min(w-40,h-40);box.set((w-side)/2,(h-side)/2,(w+side)/2,(h+side)/2);min=Math.max(side/image.getWidth(),side/image.getHeight());scale=min;x=(w-image.getWidth()*scale)/2;y=(h-image.getHeight()*scale)/2;}
  void clamp(){x=Math.min(box.left,Math.max(box.right-image.getWidth()*scale,x));y=Math.min(box.top,Math.max(box.bottom-image.getHeight()*scale,y));}
  protected void onDraw(Canvas c){c.drawColor(0xff080d12);c.drawBitmap(image,null,new RectF(x,y,x+image.getWidth()*scale,y+image.getHeight()*scale),p);p.setColor(0xaa000000);c.drawRect(0,0,getWidth(),box.top,p);c.drawRect(0,box.bottom,getWidth(),getHeight(),p);c.drawRect(0,box.top,box.left,box.bottom,p);c.drawRect(box.right,box.top,getWidth(),box.bottom,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2);p.setColor(-1);c.drawRect(box,p);p.setColor(0xaaffffff);c.drawCircle(box.centerX(),box.centerY(),box.width()/2,p);p.setStyle(Paint.Style.FILL);}
  public boolean onTouchEvent(MotionEvent e){pinch.onTouchEvent(e);if(e.getActionMasked()==0){lastX=e.getX();lastY=e.getY();}if(e.getActionMasked()==2){if(!pinch.isInProgress()&&e.getPointerCount()==1){x+=e.getX()-lastX;y+=e.getY()-lastY;clamp();invalidate();}lastX=e.getX();lastY=e.getY();}return true;}
  Bitmap result(){int left=Math.max(0,(int)((box.left-x)/scale)),top=Math.max(0,(int)((box.top-y)/scale));int side=Math.min(Math.min(image.getWidth()-left,image.getHeight()-top),Math.max(1,(int)(box.width()/scale)));return Bitmap.createScaledBitmap(Bitmap.createBitmap(image,left,top,side,side),160,160,true);}
 }
}
